package mz.bam.seeky.android;
import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import android.text.*;import java.text.DateFormat;import java.util.Date;
/** Cover-first tiles, with the same format identity in rows and grids. */
final class FileItemView extends LinearLayout {
 interface Actions {void select(Catalog.Entry entry);void favorite(Catalog.Entry entry,View target);}
 final CheckBox check;final TextView name,info,details,star;final ImageView thumbnail;final FrameLayout art;final Icons icon;final GradientDrawable background=new GradientDrawable();Catalog.Entry entry;int mode,size;
 int dp(float v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
 TextView label(int sp){TextView t=new TextView(getContext());t.setTextSize(sp);t.setEllipsize(TextUtils.TruncateAt.END);return t;}
 FileItemView(Context c,int mode,int size,Actions actions){super(c);size=IconSizing.bounded(size);this.mode=mode;this.size=size;boolean grid=mode==3||mode==5;setOrientation(grid?VERTICAL:HORIZONTAL);setGravity(grid?Gravity.TOP:Gravity.CENTER_VERTICAL);setDescendantFocusability(FOCUS_BLOCK_DESCENDANTS);setPadding(dp(10),dp(10),dp(10),dp(10));background.setCornerRadius(dp(16));setBackground(background);
  check=new CheckBox(c);check.setFocusable(false);check.setOnClickListener(v->{if(entry!=null)actions.select(entry);});art=new FrameLayout(c);icon=new Icons(c,"document",0xff7854ba);int symbol=grid?new int[]{40,52,64}[size]:new int[]{28,36,48}[size];FrameLayout.LayoutParams glyph=new FrameLayout.LayoutParams(dp(symbol),dp(symbol*1.2f),Gravity.CENTER);art.addView(icon,glyph);thumbnail=new ImageView(c);thumbnail.setScaleType(ImageView.ScaleType.FIT_CENTER);art.addView(thumbnail,new FrameLayout.LayoutParams(-1,-1));
  if(grid){FrameLayout leading=new FrameLayout(c);leading.addView(art,new FrameLayout.LayoutParams(-1,-1));leading.addView(check,new FrameLayout.LayoutParams(dp(40),dp(40),Gravity.TOP|Gravity.END));addView(leading,new LayoutParams(-1,dp(size==2?184:size==0?112:148)));}
  else{addView(check,new LayoutParams(dp(38),dp(44)));int width=size==2||mode==4?88:size==0?34:48;int height=size==2||mode==4?112:width;addView(art,new LayoutParams(dp(width),dp(height)));}
  LinearLayout copy=new LinearLayout(c);copy.setOrientation(VERTICAL);copy.setPadding(grid?0:dp(12),grid?dp(9):0,dp(4),0);name=label(grid?13:14);name.setTypeface(null,Typeface.BOLD);name.setMaxLines(grid?2:1);copy.addView(name);info=label(11);info.setMaxLines(1);copy.addView(info);details=label(11);details.setMaxLines(mode==1?4:mode==2?3:2);copy.addView(details);addView(copy,new LayoutParams(grid?-1:0,-2,grid?0:1));star=label(23);star.setGravity(Gravity.CENTER);star.setOnClickListener(v->{if(entry!=null)actions.favorite(entry,star);});if(!grid)addView(star,new LayoutParams(dp(40),dp(44)));else star.setVisibility(GONE);
 }
 void bind(Catalog.Entry e,boolean selected,int surface,int ink,int muted,int accent){entry=e;boolean grid=mode==3||mode==5;background.setColor(surface);background.setStroke(dp(selected?2:1),selected?accent:AppPalette.of(getContext()).line);check.setVisibility(e.directory?INVISIBLE:VISIBLE);check.setChecked(selected);check.setButtonTintList(android.content.res.ColorStateList.valueOf(accent));check.setContentDescription(AppLanguage.text(getContext(),selected?"Desmarcar ":"Seleccionar ")+e.name);String symbol=FileVisual.symbol(e.name,e.mime,e.directory);int color=symbol.equals("pdf")?0xffc34444:symbol.equals("word")?0xff205fa3:symbol.equals("excel")?0xff287745:accent;icon.setSymbol(symbol,color);GradientDrawable paper=new GradientDrawable();paper.setColor(AppPalette.of(getContext()).tint);paper.setCornerRadius(dp(10));art.setBackground(paper);art.setClipToOutline(true);
  name.setText(e.displayTitle());name.setTextColor(ink);info.setText((e.directory?AppLanguage.text(getContext(),"Pasta"):Rules.bytes(e.size))+" · "+AppLanguage.text(getContext(),e.displayCategory()));info.setTextColor(muted);String date=e.modified>0?DateFormat.getDateTimeInstance(DateFormat.SHORT,DateFormat.SHORT).format(new Date(e.modified)):"";String extra=mode==1?e.name+"\n"+date+(!e.author.isEmpty()?"\n"+e.author:""):mode==2?(e.snippet.isEmpty()?e.path:e.snippet):mode==4?date+"\n"+e.path:!e.author.isEmpty()?e.author:e.path;details.setText(extra);details.setTextColor(muted);details.setVisibility(grid?GONE:VISIBLE);star.setText(e.favorite?"★":"☆");star.setTextColor(e.favorite?accent:muted);star.setVisibility(grid||e.directory?GONE:VISIBLE);thumbnail.setTag(null);thumbnail.setImageDrawable(null);thumbnail.setVisibility(GONE);thumbnail.setScaleType(MediaFormats.kind(e.name,e.mime).equals("image")?ImageView.ScaleType.CENTER_CROP:ImageView.ScaleType.FIT_CENTER);setContentDescription(e.name+". "+AppLanguage.text(getContext(),e.displayCategory()));
 }
}
